{{Artes culinarias/Datos de receta
|comensales = 3
|tiempo = 10 minutos
|dificultad = 1
|ingredientes = 
* 6 {{ing|Huevo|huevos}}
* 1/2 {{ute|taza}} de {{ing|aceite de oliva}}
* 4 dientes de {{ing|ajo}}
* {{ing|Sal}} y {{ing|pimienta}}
|procedimiento = 
# En un {{ute|sartén}} colocamos el aceite de oliva y calentamos.
# Se agregan los ajos picados en trozos pequeños, se {{coc|Sofreír|sofríen}} sin dejar quemar
# Se agregan los huevos y se fríen al término de gusto.
# Antes de retirar se coloca sal y pimienta al gusto.
}}


{{Artes culinarias/Trucos|Otra forma de preparar estos huevos al ajo es revolviendo los huevos previamente en un bols junto con {{ing|perejil}} y llevar al aceite cuando los ajos estén dorando.}}

[[Categoría:Recetas|{{SUBPAGENAME}}]]
